 $('itemTable').querySelectorAll('[data-item-description]').forEach(b=>b.onclick=()=>{const item=m.items.find(x=>x.id===b.dataset.itemDescription);const dialog=document.createElement('dialog');dialog.innerHTML=`<form><h3>وصف ${escape(item.name)}</h3><textarea name="description" rows="6" maxlength="4000">${escape(item.description||'')}</textarea><div class="actions"><button>حفظ الوصف</button><button type="button" data-close>إغلاق</button></div></form>`;$('content').append(dialog);dialog.showModal();dialog.querySelector('[data-close]').onclick=()=>dialog.remove();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await api('/api/v1/catalog/items/'+item.id,{description:dialog.querySelector('textarea').value},'PATCH');dialog.remove();await refresh();notify('تم حفظ الوصف');});};});
 $('itemTable').querySelectorAll('[data-delete-item]').forEach(b=>b.onclick=()=>{if(confirm('حذف المادة؟ لا يمكن حذف مادة مرتبطة برصيد أو مستند.'))busy(b,async()=>{await api('/api/v1/catalog/items/'+b.dataset.deleteItem,undefined,'DELETE');await refresh();notify('تم حذف المادة');});});
